pub fn find(pc: u64) -> Option<&'static str> {
    let pc = pc as u32;
    let i = OPS.binary_search_by_key(&pc, |e| e.0).ok()?;
    let start = OPS[i].1 as usize;
    let end = BLOB[start..]
        .find('\n')
        .map(|k| start + k)
        .unwrap_or(BLOB.len());
    Some(&BLOB[start..end])
}
